import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./source-vector-front.png',import.meta.url).href,axis:new URL('./source-vector-axis.png',import.meta.url).href,back:new URL('./source-vector-back.png',import.meta.url).href};export function addStickers(host){const result=[];for(const face of['front','axis','back']){const v=spec.labels[face];result.push(...printedArtwork(host,{target:host.dof9Assembly.labels[face],url:sources[face],size:v.size,position:v.position,face:face==='back'?'back':'front',depth:.1,name:'DoF9 own outlined '+face+' printed label',artworkKind:'source-vector-raster'})??[]);}return result;}
